package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each sheet's settings: the roles given to user names, its clerk limit, its floor, its terms, its late percent, its policy date and its period numbering from. */
@Repository
public class Settings {

    /** The floor of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms, in days, of a sheet that has not set them. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent of a sheet that has not set one. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    private final JdbcTemplate jdbc;

    public Settings(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The user's role on the sheet: a clerk unless given another. */
    public Role role(String sheetId, String user) {
        return jdbc.query("SELECT role FROM sheet_role WHERE sheet_id = ? AND user_name = ?",
                (rs, i) -> Role.valueOf(rs.getString("role")), sheetId, user)
                .stream().findFirst().orElse(Role.CLERK);
    }

    /** Every role given on the sheet, by user name. */
    public List<RoleResponse> roles(String sheetId) {
        return jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
                (rs, i) -> new RoleResponse(rs.getString("user_name"), Role.valueOf(rs.getString("role")).show()),
                sheetId);
    }

    public void setRole(String sheetId, String user, Role role) {
        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
                sheetId, user, role.name());
    }

    /** The sheet's clerk limit, or null for no limit. */
    public BigDecimal clerkLimit(String sheetId) {
        return column("clerk_limit", sheetId);
    }

    public void setClerkLimit(String sheetId, BigDecimal limit) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, clerk_limit) KEY (sheet_id) VALUES (?, ?)", sheetId, limit);
    }

    /** The sheet's floor: a claim's live due is at least it. 1.00 unless set. */
    public BigDecimal floor(String sheetId) {
        BigDecimal floor = column("floor", sheetId);
        return floor != null ? floor : DEFAULT_FLOOR;
    }

    public void setFloor(String sheetId, BigDecimal floor) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, floor) KEY (sheet_id) VALUES (?, ?)", sheetId, floor);
    }

    /** The sheet's terms: a claim is due by its date plus this many days. 14 unless set. */
    public int terms(String sheetId) {
        BigDecimal terms = column("terms", sheetId);
        return terms != null ? terms.intValue() : DEFAULT_TERMS;
    }

    public void setTerms(String sheetId, int terms) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, terms) KEY (sheet_id) VALUES (?, ?)", sheetId, terms);
    }

    /** The sheet's late percent: an overdue claim's due gains it of its figure for every full 30 days
     *  overdue. 0.00 unless set. */
    public BigDecimal latePct(String sheetId) {
        BigDecimal pct = column("late_pct", sheetId);
        return pct != null ? pct : DEFAULT_LATE_PCT;
    }

    public void setLatePct(String sheetId, BigDecimal pct) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, late_pct) KEY (sheet_id) VALUES (?, ?)", sheetId, pct);
    }

    /** The sheet's policy date as set: a claim dated before it rounds half up, one on or after it
     *  half to even. Null when unset: then the policy date is the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        List<Date> values = jdbc.query("SELECT policy_date FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getDate("policy_date"), sheetId);
        return values.isEmpty() || values.get(0) == null ? null : values.get(0).toLocalDate();
    }

    public void setPolicyDate(String sheetId, LocalDate date) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, policy_date) KEY (sheet_id) VALUES (?, ?)",
                sheetId, date != null ? Date.valueOf(date) : null);
    }

    /** The sheet's period numbering from: while set and the sheet's today is on or after it, a
     *  claim opened is numbered within its period. Null when unset (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        List<Date> values = jdbc.query("SELECT period_numbering_from FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getDate("period_numbering_from"), sheetId);
        return values.isEmpty() || values.get(0) == null ? null : values.get(0).toLocalDate();
    }

    public void setPeriodNumberingFrom(String sheetId, LocalDate date) {
        jdbc.update("MERGE INTO sheet_setting (sheet_id, period_numbering_from) KEY (sheet_id) VALUES (?, ?)",
                sheetId, date != null ? Date.valueOf(date) : null);
    }

    /** One setting's stored value, null when the sheet has no row or the setting is unset. */
    private BigDecimal column(String column, String sheetId) {
        List<BigDecimal> values = jdbc.query("SELECT " + column + " FROM sheet_setting WHERE sheet_id = ?",
                (rs, i) -> rs.getBigDecimal(column), sheetId);
        return values.isEmpty() ? null : values.get(0);
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.regex.Pattern;
import net.officefloor.hq.app.rollup.Actor;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {
    /** An amount: 0.00 or more, with up to two decimals. */
    private static final Pattern AMOUNT = Pattern.compile("\\d{1,10}(\\.\\d{1,2})?");

    /** Terms: a whole number of days, 0 or more. */
    private static final Pattern DAYS = Pattern.compile("\\d{1,4}");

    /** A percent: 0.00 or more, with up to two decimals. */
    private static final Pattern PCT = Pattern.compile("\\d{1,5}(\\.\\d{1,2})?");

    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody SettingsRequest request,
            Out<SettingsChange> change, Out<Actor> actor) throws InvalidSheetRequestException {
        String limit = request == null || request.clerkLimit() == null ? null : request.clerkLimit().trim();
        if (limit != null && !limit.isEmpty() && !AMOUNT.matcher(limit).matches()) {
            throw new InvalidSheetRequestException("The clerk limit must be an amount with up to two decimals, or blank");
        }
        String floor = request == null || request.floor() == null ? null : request.floor().trim();
        if (floor != null && !floor.isEmpty() && !AMOUNT.matcher(floor).matches()) {
            throw new InvalidSheetRequestException("The floor must be an amount with up to two decimals, or blank");
        }
        String terms = request == null || request.terms() == null ? null : request.terms().trim();
        if (terms != null && !terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new InvalidSheetRequestException("The terms must be a whole number of days, or blank");
        }
        String late = request == null || request.latePct() == null ? null : request.latePct().trim();
        if (late != null && !late.isEmpty() && !PCT.matcher(late).matches()) {
            throw new InvalidSheetRequestException("The late percent must be a percent with up to two decimals, or blank");
        }
        String policy = request == null || request.policyDate() == null ? null : request.policyDate().trim();
        LocalDate policyDate = null;
        if (policy != null && !policy.isEmpty()) {
            try {
                policyDate = LocalDate.parse(policy);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("The policy date must be a date (yyyy-mm-dd), or blank");
            }
        }
        String numbering = request == null || request.periodNumberingFrom() == null ? null : request.periodNumberingFrom().trim();
        LocalDate numberingFrom = null;
        if (numbering != null && !numbering.isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(numbering);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("The period numbering from must be a date (yyyy-mm-dd), or blank");
            }
        }
        String by = request == null ? null : request.user();
        actor.set(new Actor(by));
        change.set(new SettingsChange(sheetId, limit != null,
                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
                floor == null ? null : floor.isEmpty() ? Settings.DEFAULT_FLOOR : new BigDecimal(floor).setScale(2),
                terms == null ? null : terms.isEmpty() ? Settings.DEFAULT_TERMS : Integer.parseInt(terms),
                late == null ? null : late.isEmpty() ? Settings.DEFAULT_LATE_PCT : new BigDecimal(late).setScale(2),
                policy != null, policyDate, numbering != null, numberingFrom, by));
    }
}
package net.officefloor.hq.app.settings;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/** The sheet's settings as the screen sees them: the clerk limit with two decimals (null for no
 *  limit), the floor with two decimals, the terms in days, the late percent with two decimals, the policy date as set (yyyy-mm-dd, null when blank), the period numbering from (yyyy-mm-dd, null when off) and the roles given, by user name. */
public record SettingsResponse(String clerkLimit, String floor, int terms, String latePct, String policyDate, String periodNumberingFrom, List<RoleResponse> roles) {
    public static SettingsResponse of(String sheetId, Settings settings) {
        BigDecimal limit = settings.clerkLimit(sheetId);
        LocalDate policyDate = settings.policyDate(sheetId);
        LocalDate numberingFrom = settings.periodNumberingFrom(sheetId);
        return new SettingsResponse(limit != null ? limit.toPlainString() : null,
                settings.floor(sheetId).toPlainString(), settings.terms(sheetId),
                settings.latePct(sheetId).toPlainString(),
                policyDate != null ? policyDate.toString() : null,
                numberingFrom != null ? numberingFrom.toString() : null, settings.roles(sheetId));
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim a person on a sheet has made, DRAFT (and unnumbered) until it is opened. `id` is null until the claim is first saved. */
public class Claim {
    private Long id;
    private final String sheetId;
    private long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal due;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;

    public Claim(Long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal due, String openedBy) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.due = due;
        this.openedBy = openedBy;
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public long getPersonId() { return personId; }
    public void setPersonId(long personId) { this.personId = personId; }
    public BigDecimal getAmount() { return amount; }
