  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ben_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-claimed")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("person-row-" + p_dot).getByTestId("person-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_dot_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await ui.setSetting(pg_uma, "floor", "3.00");
  expect(await ui.addPatron(pg_uma, p_dot, "Ben")).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ben_0, "open")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00", "from": "2026-03-10"})).toBe(true);
  const c_ben_1 = ui.must(await ui.addClaim(pg_uma, p_ben, {"amount": "4.00"}));
  expect(await ui.retire(pg_uma, p_ben, "2026-02-10")).toBe(true);
