package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet. `id` is null until the person is first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; LocalDate.MIN for the first one,
     *  which applies from the beginning of time. */
    private TreeMap<LocalDate, String> grades = new TreeMap<>();
    /** The sheet's today as it was when the person was read (null: the person is new). */
    private LocalDate today;
    /** A grade this save records, from its date (null: the save records none). */
    private DatedGrade newGrade;
    private int version;
    private int statementCount;
    private BigDecimal statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    private boolean held;
    private List<Long> patronIds = new ArrayList<>();

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, int version) {
        this.version = version;
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
        if (grade != null) this.grades.put(LocalDate.MIN, grade);
    }

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getSheetId() { return sheetId; }
    public String getName() { return name; }
    public void setName(String name) { this.name = name; }
    /** The grade in force on the sheet's today. */
    public String getGrade() { return today == null ? grades.lastEntry().getValue() : gradeOn(today); }
    /** The grade in force on `date`: the one from the latest date on or before it, the first one
     *  applying from the beginning of time. */
    public String gradeOn(LocalDate date) {
        Map.Entry<LocalDate, String> e = grades.floorEntry(date);
        return e != null ? e.getValue() : grades.firstEntry().getValue();
    }
    /** The first grade the person was given. */
    public String getFirstGrade() { return grades.firstEntry().getValue(); }
    public TreeMap<LocalDate, String> getGrades() { return grades; }
    public void setGrades(TreeMap<LocalDate, String> grades) { this.grades = grades; }
    public void setToday(LocalDate today) { this.today = today; }
    public DatedGrade getNewGrade() { return newGrade; }
    /** Record `grade` from `from` with the next save, replacing any grade from that same date. */
    public void recordGrade(String grade, LocalDate from) {
        this.newGrade = new DatedGrade(grade, from);
        LocalDate key = grades.isEmpty() ? LocalDate.MIN : from;
        grades.put(key, grade);
    }
    /** How many times the person has been saved since added. */
    public int getVersion() { return version; }
    public void setVersion(int version) { this.version = version; }
package net.officefloor.hq.app.settings;

/** Body of a settings change: the settings being set, each left out (null) when it is not being
 *  changed — the clerk limit (two decimals, blank for no limit), the floor (two decimals, blank for
 *  the default 1.00), the terms (whole days, blank for the default 14), the late percent (two decimals, blank for the default 0.00), the policy date (yyyy-mm-dd, blank for the sheet's today), the period numbering from (yyyy-mm-dd, blank for off) — and who makes the change. */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom, String user) {
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Late } from '../claims/useClaims';
import { useSheetToday } from '../sheet/useSheet';

/** A role given to a user name: clerk (the default for any name) or steward. */
export type RoleEntry = { name: string; role: string };

/** The sheet's settings as the server sends them: `clerkLimit` with two decimals, or null for no
 *  limit, `floor` with two decimals `terms` in days, `latePct` with two decimals and `policyDate` as
 *  set (yyyy-mm-dd), or null when blank: then the policy date is the sheet's today, and `periodNumberingFrom`
 *  (yyyy-mm-dd), or null when off. */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; latePct: string; policyDate: string | null; periodNumberingFrom: string | null; roles: RoleEntry[] };

/** The floor of a sheet that has not set one. */
export const DEFAULT_FLOOR = '1.00';

/** The terms, in days, of a sheet that has not set them. */
export const DEFAULT_TERMS = 14;

export const settingsKey = (sheet: string) => ['sheet', sheet, 'settings'] as const;

/** The sheet's settings, re-read whenever the sheet is loaded. */
export function useSettings(sheet: string) {
  return useQuery({
    queryKey: settingsKey(sheet),
    queryFn: () => getJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`),
    staleTime: 0,
    gcTime: 0,
  });
}

/** The sheet's floor: a claim's live due is at least it. */
export function useFloor(sheet: string): string {
  return useSettings(sheet).data?.floor ?? DEFAULT_FLOOR;
}

/** The sheet's terms: a claim is due by its date plus this many days. */
export function useTerms(sheet: string): number {
  return useSettings(sheet).data?.terms ?? DEFAULT_TERMS;
}

/** The late percent of a sheet that has not set one. */
export const DEFAULT_LATE_PCT = '0.00';

/** What makes an overdue claim's due grow: the sheet's terms, its today and its late percent. */
export function useLate(sheet: string): Late {
  const settings = useSettings(sheet).data;
  return {
    terms: settings?.terms ?? DEFAULT_TERMS,
    today: useSheetToday(sheet),
    pct: settings?.latePct ?? DEFAULT_LATE_PCT,
  };
}

export const ROLES = ['clerk', 'steward'] as const;

/** A clerk limit the server accepts: an amount with up to two decimals, or blank for no limit. */
export const LIMIT = /^(\d{1,10}(\.\d{1,2})?)?$/;

/** A late percent the server accepts: a percent with up to two decimals, or blank for 0.00. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?)?$/;

/** A policy date the server accepts: yyyy-mm-dd, or blank for the sheet's today. */
export const POLICY_DATE = /^(\d{4}-\d{2}-\d{2})?$/;

/** Terms the server accepts: a whole number of days, or blank for the default 14. */
export const DAYS = /^(\d{1,4})?$/;
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { claimsKey } from '../claims/useClaims';
import { DAYS, LIMIT, PERCENT, POLICY_DATE, ROLES, settingsKey, useSettings, type Settings } from './useSettings';

/** The settings the form sets: each null while its field is untouched, so a save leaves it as it is. */
type SettingsEdit = { clerkLimit: string | null; floor: string | null; terms: string | null; latePct: string | null; policyDate: string | null; periodNumberingFrom: string | null };

/**
 * The sheet's settings: its clerk limit (a clerk settles a claim only when its due is at or below
 * it; blank is no limit), its floor (a claim's live due is at least it; blank is the default, 1.00),
 * its terms (a claim is due by its date plus this many days; blank is the default, 14), its late
 * percent (an overdue claim's due gains it of its figure for every full 30 days; blank is 0.00),
 * its policy date (a claim dated before it rounds half up, on or after it half to even; blank is
 * the sheet's today), its period numbering from (while it is a date on or before the sheet's
 * today, a claim opened is numbered within its period; blank is off),
 * and the roles given to user names (clerk, the default, or steward). A save sets only the settings
 * whose fields were touched since the last one.
 */
function SettingsPanel({ user, sheet }: { user: string; sheet: string }) {
  const queryClient = useQueryClient();
  const { data } = useSettings(sheet);
  const base = `/api/sheets/${encodeURIComponent(sheet)}`;
  const [edit, setEdit] = useState<SettingsEdit>({ clerkLimit: null, floor: null, terms: null, latePct: null, policyDate: null, periodNumberingFrom: null });
  const [limitInvalid, setLimitInvalid] = useState(false);
  const [name, setName] = useState('');
  const [role, setRole] = useState('');
  const [roleInvalid, setRoleInvalid] = useState(false);

  const submitOnce = useSubmitOnce();
  const saveSettings = useMutation({
    mutationFn: (e: SettingsEdit) => postJson<Settings>(`${base}/settings`, { ...e, user }),
    onSuccess: (saved) => {
      setEdit({ clerkLimit: null, floor: null, terms: null, latePct: null, policyDate: null, periodNumberingFrom: null });
      queryClient.setQueryData(settingsKey(sheet), saved);
      // The policy date decides how each claim's live figures round.
      return queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
  });
  const saveRole = useMutation({
    mutationFn: (r: { name: string; role: string }) => postJson<Settings>(`${base}/roles`, { ...r, user }),
    onSuccess: (saved) => {
      setName('');
      setRole('');
      queryClient.setQueryData(settingsKey(sheet), saved);
    },
  });

  // An error goes as soon as its form is changed or submitted again.
  const clearSettingsError = () => {
    saveSettings.reset();
    setLimitInvalid(false);
  };
  // A field is set by the next save once it has been touched, starting from the value in force.
  const touch = (key: keyof SettingsEdit, current: string) =>
    setEdit((was) => (was[key] !== null ? was : { ...was, [key]: current }));
  const clearRoleError = () => {
    saveRole.reset();
    setRoleInvalid(false);
  };

  return (
    <section data-testid="settings-panel">
      <h2>Settings</h2>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          const limit = edit.clerkLimit?.trim() ?? null;
          const floor = edit.floor?.trim() ?? null;
          const terms = edit.terms?.trim() ?? null;
          const latePct = edit.latePct?.trim() ?? null;
          const policyDate = edit.policyDate?.trim() ?? null;
          const periodNumberingFrom = edit.periodNumberingFrom?.trim() ?? null;
          if (
            (limit !== null && !LIMIT.test(limit)) ||
            (floor !== null && !LIMIT.test(floor)) ||
            (terms !== null && !DAYS.test(terms)) ||
            (latePct !== null && !PERCENT.test(latePct)) ||
            (policyDate !== null && !POLICY_DATE.test(policyDate)) ||
            (periodNumberingFrom !== null && !POLICY_DATE.test(periodNumberingFrom))
          ) {
            // Refused here, before anything is sent: the store and the audit file are untouched.
            saveSettings.reset();
            setLimitInvalid(true);
            return;
          }
          setLimitInvalid(false);
          submitOnce(() => saveSettings.mutateAsync({ clerkLimit: limit, floor, terms, latePct, policyDate, periodNumberingFrom }));
        }}
      >
        {/* While a save is in flight the limit in force is not yet known: saving the same value again
            shows it only once the save has landed. */}
        Clerk limit:{' '}
        <strong data-testid="setting-clerk-limit-current">
          {saveSettings.isPending ? '' : (data?.clerkLimit ?? '')}
        </strong>{' '}
        <label>
          Set to{' '}
          <input
            data-testid="setting-clerk-limit"
            placeholder="blank: no limit"
            value={edit.clerkLimit ?? (data?.clerkLimit ?? '')}
            onFocus={() => touch('clerkLimit', data?.clerkLimit ?? '')}
            onChange={(e) => {
              setEdit((was) => ({ ...was, clerkLimit: e.target.value }));
              clearSettingsError();
            }}
          />
        </label>{' '}
        Floor:{' '}
        <strong data-testid="setting-floor-current">
          {saveSettings.isPending ? '' : (data?.floor ?? '')}
        </strong>{' '}
        <label>
          Set to{' '}
          <input
            data-testid="setting-floor"
            placeholder="blank: 1.00"
            value={edit.floor ?? (data?.floor ?? '')}
            onFocus={() => touch('floor', data?.floor ?? '')}
            onChange={(e) => {
              setEdit((was) => ({ ...was, floor: e.target.value }));
              clearSettingsError();
            }}
          />
        </label>{' '}
        Terms:{' '}
        <strong data-testid="setting-terms-current">
          {saveSettings.isPending ? '' : (data?.terms ?? '')}
        </strong>{' '}
        <label>
          Set to{' '}
          <input
            data-testid="setting-terms"
            placeholder="blank: 14 days"
            value={edit.terms ?? String(data?.terms ?? '')}
            onFocus={() => touch('terms', String(data?.terms ?? ''))}
            onChange={(e) => {
              setEdit((was) => ({ ...was, terms: e.target.value }));
              clearSettingsError();
            }}
          />
        </label>{' '}
        Late percent:{' '}
        <strong data-testid="setting-late-pct-current">
          {saveSettings.isPending ? '' : (data?.latePct ?? '')}
        </strong>{' '}
        <label>
          Set to{' '}
          <input
            data-testid="setting-late-pct"
            placeholder="blank: 0.00"
            value={edit.latePct ?? (data?.latePct ?? '')}
            onFocus={() => touch('latePct', data?.latePct ?? '')}
            onChange={(e) => {
              setEdit((was) => ({ ...was, latePct: e.target.value }));
              clearSettingsError();
            }}
          />
        </label>{' '}
        Policy date:{' '}
        <strong data-testid="setting-policy-date-current">
          {saveSettings.isPending ? '' : (data?.policyDate ?? '')}
        </strong>{' '}
        <label>
          Set to{' '}
          <input
            data-testid="setting-policy-date"
            placeholder="blank: the sheet's today"
            value={edit.policyDate ?? (data?.policyDate ?? '')}
            onFocus={() => touch('policyDate', data?.policyDate ?? '')}
            onChange={(e) => {
              setEdit((was) => ({ ...was, policyDate: e.target.value }));
              clearSettingsError();
            }}
          />
        </label>{' '}
        Period numbering from:{' '}
        <strong data-testid="setting-period-numbering-from-current">
          {saveSettings.isPending ? '' : (data?.periodNumberingFrom ?? '')}
        </strong>{' '}
        <label>
          Set to{' '}
          <input
            data-testid="setting-period-numbering-from"
            placeholder="blank: off"
            value={edit.periodNumberingFrom ?? (data?.periodNumberingFrom ?? '')}
            onFocus={() => touch('periodNumberingFrom', data?.periodNumberingFrom ?? '')}
            onChange={(e) => {
              setEdit((was) => ({ ...was, periodNumberingFrom: e.target.value }));
              clearSettingsError();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="settings-save" disabled={saveSettings.isPending}>
          Save
        </button>
        {(limitInvalid || saveSettings.isError) && (
          <span data-testid="settings-error" role="alert">
            {' '}The clerk limit and the floor must be amounts with up to two decimals (a blank limit is no
            limit, a blank floor is 1.00), the terms a whole number of days (blank is 14), and the late percent a percent with up to
